    points = [[t^k | k <- [1..4 :: Int]] | t <- [1..8]]
    rows =
        [([-482,167,-22,1],-336)
        ,([-358,137,-20,1],-240)
        ,([-252,109,-18,1],-160)
        ,([-164,83,-16,1],-96)
        ,([-94,59,-14,1],-48)
        ,([50,-35,10,-1],24)
        ,([78,-49,12,-1],40)
        ,([112,-65,14,-1],60)
        ,([152,-83,16,-1],84)
        ,([154,-71,14,-1],120)
        ,([198,-103,18,-1],112)
        ,([216,-91,16,-1],180)
        ,([288,-113,18,-1],252)
        ,([342,-119,18,-1],360)
        ,([370,-137,20,-1],336)
        ,([450,-145,20,-1],504)
        ,([572,-173,22,-1],672)
        ,([638,-179,22,-1],840)
